import{_ as o,o as e,c as s,aj as a}from"./framework.js";const b=JSON.parse('{"title":"k.site.runJob | Api / Site | Documentation","description":"k.site.runJob in Kooboo: 站点 定时任务（SiteJob） 在后台配置名称、调度与 内联 KScript。运行时由 JobService 在服务端执行，不经过前台 HTTP。","frontmatter":{"title":"k.site.runJob | Api / Site | Documentation","description":"k.site.runJob in Kooboo: 站点 定时任务（SiteJob） 在后台配置名称、调度与 内联 KScript。运行时由 JobService 在服务端执行，不经过前台 HTTP。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/api/site/job.html"}]]},"headers":[],"relativePath":"zh/api/site/job.md","filePath":"api/site/job.md","lastUpdated":1783042246000}'),i={name:"zh/api/site/job.md"};function d(r,t,n,c,l,h){return e(),s("div",null,[...t[0]||(t[0]=[a('<h1 id="k-site-runjob" tabindex="-1">k.site.runJob <a class="header-anchor" href="#k-site-runjob" aria-label="Permalink to &quot;k.site.runJob&quot;">​</a></h1><blockquote><p>对应后台 <a href="/kb-docs/zh/cms/development/jobs.html">开发 → 定时任务</a></p></blockquote><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>站点 <strong>定时任务（SiteJob）</strong> 在后台配置名称、调度与 <strong>内联 KScript</strong>。运行时由 <code>JobService</code> 在服务端执行，不经过前台 HTTP。</p><p>脚本侧仅提供 <strong>触发</strong> 与（部分版本）<strong>状态查询</strong>；任务的增删改请在后台完成。</p><div class="tip custom-block"><p class="custom-block-title">先配后台</p><p>在 <a href="/kb-docs/zh/cms/development/jobs.html#任务列表">任务列表</a> 中 <strong>添加任务</strong> 并保存后，方可在其它 Code 中按 <strong>名称</strong> 调用 <code>k.site.runJob</code>。</p></div><h2 id="k-site-runjob-name" tabindex="-1">k.site.runJob(name) <a class="header-anchor" href="#k-site-runjob-name" aria-label="Permalink to &quot;k.site.runJob(name)&quot;">​</a></h2><p>异步执行指定任务一次（与列表 <strong>运行</strong> 等效，日志说明为 <code>Manual trigger from kscript</code>）。</p><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>name</code></td><td><code>string</code></td><td>是</td><td>任务 <strong>名称</strong> 或任务 Id（GUID 字符串）</td></tr></tbody></table><p><strong>返回：</strong> <code>void</code>。</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">k.site.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">runJob</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;nightly_sync&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>任务不存在时抛出 <code>Job not found</code>。</p><div class="warning custom-block"><p class="custom-block-title">与调度器的关系</p><p><code>runJob</code> <strong>不</strong> 替代周期调度；重复任务仍按后台 <strong>开始时间</strong> 与 <strong>间隔</strong> 自动执行。手动运行可在站点未发布时用于调试。</p></div><h2 id="执行环境" tabindex="-1">执行环境 <a class="header-anchor" href="#执行环境" aria-label="Permalink to &quot;执行环境&quot;">​</a></h2><ul><li>使用当前站点的服务端执行上下文。</li><li>代码来自 <code>SiteJob.Code</code> 字段（后台 Monaco 保存），以 <strong>Module</strong> 脚本类型、<strong>长任务</strong> 选项执行。</li><li>可使用与其它服务端 Code 相同的 <code>k.*</code> API（<code>k.DB</code>、<code>k.content</code>、<code>k.mail</code> 等）。</li></ul><p>执行结果写入中心 <strong>JobLog</strong>（后台 <strong>已完成</strong> / <strong>失败</strong> 页签）。</p><h2 id="与-k-site-codes-的区别" tabindex="-1">与 k.site.codes 的区别 <a class="header-anchor" href="#与-k-site-codes-的区别" aria-label="Permalink to &quot;与 k.site.codes 的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th><strong>SiteJob（定时任务）</strong></th><th><strong>k.site.codes</strong></th></tr></thead><tbody><tr><td>配置</td><td>开发 → 定时任务</td><td>开发 → 代码</td></tr><tr><td>触发</td><td>调度器 / <code>runJob</code></td><td>HTTP 路由、事件、页面引用</td></tr><tr><td>代码存储</td><td><code>SiteJob.Code</code> 内联</td><td><code>Code</code> 资源 <code>body</code></td></tr></tbody></table><p>若希望复用同一段逻辑，可将公共函数放在 Code 中，在任务脚本里通过约定调用（需自行 <code>import</code> 或内联，Kooboo 任务默认不自动绑定 Code Id）。</p><h2 id="模块任务" tabindex="-1">模块任务 <a class="header-anchor" href="#模块任务" aria-label="Permalink to &quot;模块任务&quot;">​</a></h2><p>模块包内 <code>module.config</code> 的 <strong>task</strong> 与事件由 <code>k.module</code> / 模块调度处理，<strong>不是</strong> <code>k.site.runJob</code>。见 <a href="/kb-docs/zh/api/module/">k.module</a>。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/kb-docs/zh/cms/development/jobs.html">定时任务（CMS）</a></li><li><a href="./">k.site</a></li><li><a href="./code.html">k.site.codes</a></li></ul>',23)])])}const k=o(i,[["render",d]]);export{b as __pageData,k as default};
